         background: rgba(37, 99, 235, 0.04);
       }

       .checkbox-row {
         display: flex;
         gap: 12px;
         align-items: flex-start;
       }

       input[type="checkbox"] {
         width: 1.1rem;
         height: 1.1rem;
         margin-top: 0.2rem;
         accent-color: var(--accent);
         flex: none;
       }

       label {
         font-weight: 600;
         line-height: 1.5;
         cursor: pointer;
       }

       .helper-text {
         margin: 0;
         color: var(--muted);
         font-size: 0.95rem;
         line-height: 1.5;
       }

       .actions {
         display: flex;
         justify-content: flex-end;
       }

       button {
         border: 0;
         border-radius: 999px;
         padding: 0.9rem 1.3rem;
         font: inherit;
         font-weight: 700;
         color: white;
         background: linear-gradient(135deg, var(--accent), #4f46e5);
         box-shadow: 0 10px 20px rgba(37, 99, 235, 0.24);
         cursor: pointer;
       }

       button:hover {
         background: linear-gradient(135deg, var(--accent-hover), #4338ca);
       }

       button:focus-visible,
       input:focus-visible {
         outline: 3px solid rgba(37, 99, 235, 0.25);
         outline-offset: 2px;
       }
     </style>
   </head>
   <body>
     <div id="root"></div>

     <script>
       function ConsentCheckbox() {
         return `
           <div class="form-field">
             <div class="checkbox-row">
               <input id="terms" name="terms" type="checkbox" required />
               <div>
                 <label for="terms">I agree to the Terms of Use</label>
                 <p class="helper-text">Required to continue using the product.</p>
               </div>
             </div>
           </div>
         `;
       }

       function App() {
         return `
           <main class="page">
             <section class="card" aria-labelledby="form-title">
               <p class="eyebrow">Consent</p>
               <h1 id="form-title">Accept the terms to continue</h1>
               <p class="description">Please confirm your agreement before submitting the form.</p>
               <form>
                 ${ConsentCheckbox()}
                 <div class="actions">
                   <button type="submit">Submit</button>
                 </div>
               </form>
             </section>
           </main>
         `;
       }

       document.getElementById("root").innerHTML = App();
     </script>
   </body>
 </html>

